style.css:
@font-face {
    font-family: MyCustomFont;
    src: local(Heiti TC), local("Noto Sans CJK SC");
    /* no unicode-range; default to all characters */
}

/* Latin characters 專用 */
@font-face {
    font-family: MyCustomFont;
    /* 同樣的 font-family */
    unicode-range: U+00-024F;
    /* Latin, Latin1 Sup., Ext-A, Ext-B */
    src: local("Noto Sans CJK SC"), /* OS X preferred */
    local("Noto Sans CJK SC");
    /* Other OS */
}

/* 注音符號專用 */
@font-face {
    font-family: MyCustomFont;
    /* 同樣的 font-family */
    unicode-range: U+3100-312F;
    /* Bopomofo */
    src: local("Noto Sans CJK SC"), /* OS X */
    local("Noto Sans CJK SC");
    /* Windows Vista+ */
}

/* 日文假名專用 */
@font-face {
    font-family: MyCustomFont;
    /* 同樣的 font-family */
    unicode-range: U+3040-30FF;
    /* Hiragana, Katakana */
    src: local("Noto Sans CJK JP"), /* OS X */
    local("Noto Sans CJK JP");
    /* Windows Vista+ */
}

* {
    font-family: MyCustomFont, sans-serif;
}

a {
    font-family: MyCustomFont, sans-serif;
}
div {
    font-family: MyCustomFont, sans-serif;
}
